/* PROVENANCE: VENDOR pin tables, every part and package: ISE .chp, checked by pinvendor.py on all 42 (§205) */
static const int PIN_TABLE_N = 4089;

int pin_table_lookup_str(const char *device, const char *pkg, int fb, int mc,
                         const char **pin) {
    for (int i = 0; i < PIN_TABLE_N; i++) {
        const PinEnt *e = &PIN_TABLE[i];
        if (e->fb == fb && e->mc == mc &&
            strcmp(e->dev, device) == 0 && strcmp(e->pkg, pkg) == 0) {
            if (pin) *pin = e->pin;
            return 1;
        }
    }
    return 0;
}

/* A wire-bond package numbers its pins ("40"); a BGA names balls ("D1"), and
 * row P is a real row there ("P12" is a ball). Which kind a part is comes from
 * its own pin table, never from the package name: the QFN parts are spelled
 * FG32/FG48 but have numbered pins, while FG324 is a BGA. 0 when the part has
 * no table. */
int pin_table_wire_bond(const char *device, const char *pkg) {
    int any = 0;
    for (int i = 0; i < PIN_TABLE_N; i++) {
        const PinEnt *e = &PIN_TABLE[i];
        if (strcmp(e->dev, device) || strcmp(e->pkg, pkg)) continue;
        any = 1;
        for (const char *p = e->pin; *p; p++) if (*p < '0' || *p > '9') return 0;
    }
    return any;
}

/* A pin as spelled in a UCF or the pin table, reduced to one spelling so the
 * two can be compared. On a wire-bond part UCF accepts a pin bare or with a P
 * prefix, so "P1" and "1" both become "1". On a BGA nothing is stripped:
 * "P1" is ball P1 and "1" is no ball at all. Upper-cased either way. */
void pin_canon(const char *loc, int wire_bond, char *out, size_t n) {
    const char *s = loc ? loc : "";
    size_t i = 0;
    if (wire_bond && (s[0] == 'P' || s[0] == 'p') && s[1]) {
        const char *d = s + 1;
        while (*d >= '0' && *d <= '9') d++;
        if (!*d) s++;
    }
    for (; *s && i + 1 < n; s++) out[i++] = (char)toupper((unsigned char)*s);
    if (n) out[i] = 0;
}

void pintable_list(void) {
    printf("Decode works on any CoolRunner-II device. Pin numbers and real signal\n");
    printf("names need a built-in pinout; those are listed below.\n\n");
    printf("%-10s %-7s %s\n", "device", "package", "bonded macrocells");
    const char *ld = "", *lp = ""; int cnt = 0;
    for (int i = 0; i <= PIN_TABLE_N; i++) {
        int last = (i == PIN_TABLE_N);
        if (!last && strcmp(PIN_TABLE[i].dev, ld) == 0 && strcmp(PIN_TABLE[i].pkg, lp) == 0) { cnt++; continue; }
        if (cnt) printf("%-10s %-7s %d\n", ld, lp, cnt);
        if (last) break;
        ld = PIN_TABLE[i].dev; lp = PIN_TABLE[i].pkg; cnt = 1;
    }
}
